<?php
/**
 * install5.php — Deploy fixed import.php + updated header.php
 * Upload to /public_html/warehouse/install5.php
 * Visit while logged in as admin, then DELETE the file.
 */
require_once __DIR__ . '/config/config.php';
requireLogin();
if (!can('users','view')) { die('Admin access required.'); }

$base  = __DIR__;
$files = [
    'modules/admin/import.php' => base64_decode(''),
    'includes/header.php'      => base64_decode(''),
];

$ok  = 0;
$err = 0;
$log = [];
foreach ($files as $rel => $content) {
    $path = $base . '/' . $rel;
    $dir  = dirname($path);
    if (!is_dir($dir)) { mkdir($dir, 0755, true); }
    if (file_put_contents($path, $content) !== false) {
        $ok++;
        $log[] = '<span class="text-success">&#10003; ' . htmlspecialchars($rel) . '</span>';
    } else {
        $err++;
        $log[] = '<span class="text-danger">&#10007; ' . htmlspecialchars($rel) . '</span>';
    }
}
?><!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>install5</title>
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">
</head><body class="p-4">
<h4>install5.php — Deploy Results</h4>
<p><?= $ok ?> written, <?= $err ?> failed.</p>
<ul><?php foreach ($log as $l) echo '<li>' . $l . '</li>'; ?></ul>
<?php if ($err===0): ?>
<div class="alert alert-success mt-3">Done! <strong>Delete this file now:</strong> cPanel → File Manager → warehouse/install5.php → Delete</div>
<?php else: ?>
<div class="alert alert-danger mt-3">Some files failed. Check folder permissions.</div>
<?php endif; ?>
</body></html>
